import json
with open('/tmp/saved_apt.txt') as f:
    lines = f.readlines()
for line in lines:
    if line.startswith('data: '):
        data = json.loads(line[6:])
        text = data['result']['content'][0]['text']
        inner = json.loads(text)
        result = inner['result']
        if isinstance(result, str):
            apts = json.loads(result)
        else:
            apts = result
        for k, v in apts.items():
            if v['price'] < 1500:
                print(f"REMOVE: {v['name']} - ${v['price']} - ID: {k}")
            else:
                print(f"KEEP: {v['name']} - ${v['price']}")
